  if(imported.effects.length) imported.warnings.push('增伤沿用当前引擎的后置逐条结算；导入顺序是来源顺序，尚未确认为游戏实际执行顺序，可在每条“更多”中调整。');
  if(typeof c.killerOverride==='boolean')imported.bossKiller=c.killerOverride;
  return imported;
}

