  const sourceIds=original.sourceIds?.length?original.sourceIds:!original.edited&&catalogId&&native.has(catalogId)?[...native.get(catalogId)]:[];
  const item={...original,catalogId,sourceIds},key=catalogId||original.id;
  if(!items.has(key)||sourceIds.length&&!items.get(key).sourceIds.length)items.set(key,item);
 }
 snapshot={...snapshot,items:[...items.values()]};
 const represented=new Set(snapshot.sourceIds||[]),selected=new Set(snapshot.items.flatMap(s=>s.sourceIds||[]));
 const rows=baseReport.rows.filter(r=>!represented.has(r.sourceId)||selected.has(r.sourceId));
 const extra=snapshot.items.filter(s=>!s.sourceIds?.length||s.edited).map(s=>({id:`loadout:${s.id}`,catalogId:s.catalogId,edited:s.edited,name:s.name,text:s.text,group:'common'}));
 const editedIds=new Set(snapshot.items.filter(s=>s.edited).flatMap(s=>s.sourceIds||[]));
 const seeds=Object.values(Object.groupBy(baseReport.rows,r=>r.sourceId)).map(rs=>({id:rs[0].sourceId,name:rs[0].sourceName,text:rs[0].sourceText,rules:rs.map(r=>r.rule)}));
 const catalog=buildCatalog(extra,seeds,templates).map(s=>s.unknown&&simpleLoadoutRules(s)?{...s,unknown:false,rules:simpleLoadoutRules(s)}:s);
 const additions=catalog.flatMap(s=>s.rules.map(rule=>({sourceId:s.id,sourceName:s.name,sourceText:s.text,group:s.group,status:'active',rule})));
 return retargetReport({...baseReport,rows:[...rows.filter(r=>!editedIds.has(r.sourceId)),...additions]},selection);
}

export function prepareLoadoutPreview({baseReport,snapshot,selection,input,baseCap=9999,baseCritRate=0,templates={},selectedBuffs=[],runtimeAnchor=[],criticalAnchor=null,manualDefenseRatio=null}){
 const raceIds={'战士':'soldier','狙击手':'sniper','骑士':'knight','魔法师':'sorcerer','兽':'beast','植物':'plant','昆虫':'insect','鸟':'bird','魔法生物':'creature','不死生物':'undead','石':'stone','机械':'machine','精灵':'spirit','龙':'dragon','神':'god','鱼':'fish'};
 selection={...selection,boss:input.boss===true,back:input.back,air:input.air,ailment:input.ailment,ground:input.ground,stunned:input.stunned===true,weakness:input.weakness===true,
  enemyRaces:input.races?.length?input.races.map(r=>raceIds[r]||r):null};
 const report=buildLoadoutReport(baseReport,snapshot,selection,templates);
 const unresolved=[];
 for(const row of report.rows)if(row.status==='pending')unresolved.push({name:row.sourceName,text:row.sourceText,reason:row.reasons.join('；')||'尚未识别'});
 // Keep known effects calculable while exposing unmapped operations explicitly.
 const safeRows=report.rows.filter(r=>r.status==='active').map(row=>{
  const effects=row.rule.effects.filter(effect=>{
   const one=buildDamageImport({...report,rows:[{...row,rule:{...row.rule,effects:[effect]}}]});
   if(one.blockers.length){unresolved.push({name:row.sourceName,text:row.sourceText,reason:one.blockers.join('；')});return false;}
   return true;
  });return {...row,rule:{...row.rule,effects}};
 });
 const safe={...report,rows:safeRows},imported=buildDamageImport(safe);
 if(imported.blockers.length)throw new Error(imported.blockers.join('；'));
 const base=baseReport.profile.baseStats,equipment=baseReport.profile.equipment;
 function panelFor(source){return calculateWebsitePanel(base,source,{equipment});}
 // Attributes and damage use the same current scenario. A saved reader HP
 // state must not pin Moonlight or near-death stat bonuses in the preview.
 const panelReport=report;
 const panel=panelFor(panelReport),key=selection.statReference==='int'?'intelligence':selection.statReference==='str'?'attack':null;
 for(const p of Object.values(panel.stats))for(const reason of p.issues)unresolved.push({name:p.label,text:'',reason});
 const buffsFor=stat=>{
  const known=stat.buffs.flatMap(b=>{const normalized=normalizeRuntimeBuff(b,stat.key);if(normalized)return [normalized];unresolved.push({name:b.source,text:'',reason:'实时属性增益的叠加类型尚未识别，暂未计入'});return [];});
  // An observed runtime buff is retained only while its source still exists;
  // selected HP conditions and selected spells are evaluated anew.
  const existing=new Set(panelReport.rows.filter(r=>r.status==='active').map(r=>r.sourceName));
  const anchors=runtimeAnchor.filter(b=>!b.hpCondition&&!b.activationCondition&&(!b.source||existing.has(b.source))&&!known.some(x=>x.runtime.stackGroup===b.runtime.stackGroup));
  const selected=selectedBuffs.filter(b=>b.stat===stat.key).map(b=>normalizeRuntimeBuff({id:b.id,source:b.name,value:b.statPercent,runtime:b.runtime},stat.key));
  if(selected.some(b=>!b))throw new Error('所选魔法增益的类型尚未确认');
  const result=combineRuntimeBuffs([...known,...anchors],selected);
  if(!result.ok)throw new Error(result.reason);return result.percent;
 };
 const next={...structuredClone(input),effects:[...imported.effects,...input.effects.filter(e=>!e.importId)],cap:baseCap+imported.capAdded+magicBuffCap(selectedBuffs,imported.skillType,imported.reference),criticalCapAdded:imported.criticalCapAdded,
  defenseRatio:Number.isFinite(manualDefenseRatio)?manualDefenseRatio:imported.defenseRatio,
  killerCorrection:imported.killerCorrection,specialAttack:selection.specialAttack===true,critRate:selection.criticalEnabled?Math.min(100,Math.max(0,(criticalAnchor?criticalAnchor.rate-criticalAnchor.contribution:baseCritRate)+imported.critAdded)):0};
 let projectStatPercent;
 if(key){
  const stat=panel.stats[key];
  if(!Number.isFinite(stat.beforeBuff)||stat.beforeBuff<=0)throw new Error(`${stat.label}缺少有效基础值，请先补齐角色属性`);
  const runtime=buffsFor(stat);
  next.attackBasis='layers';next.attackBase=stat.beforeBuff+stat.crossAdd;next.runtimeStatPercent=runtime;next.attack=Math.floor(next.attackBase*(100+runtime)/100);
  panel.values[key]=next.attack;
  if(!stat.issues.length)projectStatPercent=percent=>{
   const row={sourceId:'recommend-stat',sourceName:'属性推荐',status:'active',rule:{id:'recommend-stat',review:'ready',conditions:[],effects:[{type:'stat',target:stat.label,value:percent,unit:'%'}]}};
   const changed=panelFor({...panelReport,rows:[...panelReport.rows,row]}).stats[key];
   if(changed.issues.length)throw new Error(changed.issues.join('；'));
   const attackBase=changed.beforeBuff+changed.crossAdd;
   return {...structuredClone(next),attackBase,attack:Math.floor(attackBase*(100+runtime)/100)};
  };
 }
 if(selection.dualWield){
  next.hitMultiplier=selection.hitMultiplier??(imported.hitSources.length?imported.hitMultiplier:2);
  next.hitDamageRatio=selection.hitDamageRatio??(imported.hitSources.length?imported.hitDamageRatio:0.6);
  next.hitScaleStage=selection.hitScaleStage||imported.hitScaleStage||(imported.hitSources.length?input.hitScaleStage:'core');
 }else{next.hitMultiplier=1;next.hitDamageRatio=1;}
 return {input:next,report:safe,imported,panel,projectStatPercent,unresolved:[...new Map(unresolved.map(x=>[JSON.stringify(x),x])).values()]};
}

dist/styles.css.beforeText:
:root {
  color-scheme: light;
  --navy: #203864;
  --navy-deep: #142743;
  --blue: #4472c4;
  --blue-strong: #2f5597;
  --blue-soft: #d9e7f7;
  --blue-pale: #edf4fb;
  --grid: #aebbd0;
  --ink: #172033;
  --muted: #627087;
  --paper: #ffffff;
  --canvas: #e8eef6;
  --shadow: 0 12px 30px rgba(25, 52, 91, 0.11);
  font-family: "Microsoft YaHei", "PingFang SC", "Noto Sans CJK SC", system-ui, sans-serif;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  min-width: 320px;
  background: var(--canvas);
  color: var(--ink);
  font-size: 16px;
}

button, input, textarea { font: inherit; }

.site-header {
  min-height: 78px;
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px clamp(16px, 3vw, 46px);
  color: #fff;
  background: linear-gradient(120deg, var(--navy-deep), var(--navy) 52%, var(--blue-strong));
  border-bottom: 4px solid #88aee4;
}

.brand-mark {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border: 1px solid rgba(255,255,255,.58);
  background: rgba(255,255,255,.12);
  font-weight: 800;
  letter-spacing: .04em;
}

.site-header h1 {
  margin: 0;
  font-size: clamp(1.18rem, 2vw, 1.55rem);
  line-height: 1.25;
}

.site-header p {
  margin: 4px 0 0;
  color: #d9e8ff;
  font-size: .875rem;
}

.brand-copy { min-width: 0; }

.header-nav-link {
  margin-left: auto;
  padding: 9px 14px;
  border: 1px solid rgba(255,255,255,.62);
  color: #fff;
  text-decoration: none;
  font-size: .9rem;
  font-weight: 700;
  white-space: nowrap;
  background: rgba(255,255,255,.1);
}

.header-nav-link:hover { background: rgba(255,255,255,.2); }
.header-actions { display:flex; flex-wrap:wrap; gap:8px; margin-left:auto; }
.header-actions .header-nav-link { margin-left:0; }

main { padding: 18px clamp(10px, 2vw, 28px) 42px; }

.workspace {
  width: min(1900px, 100%);
  margin: 0 auto;
  background: var(--paper);
  border: 1px solid #c9d4e4;
  box-shadow: var(--shadow);
}

.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 14px 16px;
  background: #f8fbff;
  border-bottom: 1px solid #cad6e6;
}

.search-box {
  width: min(620px, 100%);
  min-height: 44px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 8px 0 13px;
  background: #fff;
  border: 2px solid #9db6d7;
}

.search-box:focus-within {
  border-color: var(--blue);
  box-shadow: 0 0 0 3px rgba(68,114,196,.14);
}

.search-icon { color: var(--blue-strong); font-size: 1.25rem; }

.search-box input {
  width: 100%;
  min-width: 0;
  border: 0;
  outline: 0;
  color: var(--ink);
  background: transparent;
}

.search-box button,
.back-top {
  border: 1px solid #9fb2cc;
  background: #fff;
  color: var(--blue-strong);
  cursor: pointer;
}

.search-box button { padding: 6px 10px; white-space: nowrap; }
.back-top { padding: 8px 12px; }
.search-box button:hover, .back-top:hover { background: var(--blue-pale); }

.result-summary {
  color: var(--muted);
  font-size: .875rem;
  white-space: nowrap;
}

.sheet-tabs {
  display: flex;
  gap: 2px;
  overflow-x: auto;
  padding: 9px 10px 0;
  background: #dbe5f1;
  border-bottom: 1px solid #9fb0c7;
  scrollbar-width: thin;
}

.sheet-tab {
  flex: 0 0 auto;
  min-height: 40px;
  padding: 8px 13px;
  border: 1px solid #9fb0c7;
  border-bottom: 0;
  background: #edf2f8;
  color: #30445f;
  cursor: pointer;
  font-size: .9rem;
}

.sheet-tab:hover { background: #fff; }

.sheet-tab[aria-selected="true"] {
  position: relative;
  z-index: 1;
  background: #fff;
  color: var(--blue-strong);
  font-weight: 700;
}

.sheet-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 12px;
  padding: 18px 16px 12px;
}

.sheet-kicker {
  display: block;
  margin-bottom: 2px;
  color: var(--muted);
  font-size: .76rem;
  letter-spacing: .08em;
}

.sheet-heading h2 { margin: 0; font-size: 1.35rem; color: var(--navy); }

.edit-hint {
  display: inline-block;
  margin-top: 5px;
  color: var(--muted);
  font-size: .8rem;
}

.table-area { padding: 0 12px 18px; }

.split-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(960px, 1fr));
  gap: 18px;
  overflow-x: auto;
  padding-bottom: 4px;
}

.table-scroll { overflow-x: auto; }

.excel-table {
  color: #111;
  width: 100%;
  min-width: 780px;
  border-collapse: collapse;
  table-layout: fixed;
  font-size: .84rem;
  line-height: 1.55;
}

.excel-table col.type { width: 10%; }
.excel-table col.name { width: 18%; }
.excel-table col.effect { width: 60%; }
.excel-table col.rating { width: 7%; }
.excel-table col.action { width: 5%; }
.excel-table.all-skills col.effect { width: 70%; }

/* Ordinary list follows the workbook; the labeling table keeps its own layout. */
.skill-list-table { min-width: 960px; font-size: .875rem; }
.skill-list-table col.type { width: 10%; }
.skill-list-table col.name { width: 16%; }
.skill-list-table col.sc { width: 6%; }
.skill-list-table col.effect { width: 34%; }
.skill-list-table col.sources { width: 24%; }
.skill-list-table col.rating { width: 5%; }
.skill-list-table col.action { width: 5%; }
.skill-list-table.all-skills col.name { width: 20%; }
.skill-list-table.all-skills col.effect { width: 40%; }
.skill-list-table .source-list > div + div { margin-top: 4px; }

.excel-table th,
.excel-table td {
  border: 1px solid var(--grid);
  padding: 6px 7px;
  vertical-align: top;
  background: #fff;
  overflow-wrap: anywhere;
}

.excel-table tbody tr,
.excel-table tbody td {
  height: auto;
}

.cell-content {
  width: 100%;
  height: auto;
  overflow: visible;
  padding: 2px 3px;
}

.cell-content.cell-center {
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
}

.excel-table thead .book-title th {
  padding: 10px;
  color: #111;
  background: #fff;
  font-size: .95rem;
  letter-spacing: .02em;
  text-align: center;
}

.excel-table thead .column-title th {
  position: sticky;
  top: 0;
  z-index: 2;
  color: #111;
  background: #fff;
  font-weight: 700;
  text-align: center;
}

.skill-list-table thead .book-title th { color: #fff; background: var(--navy); }
.skill-list-table thead .column-title th { color: #fff; background: var(--blue); }

.judgment-cell .judgment-ready { color: #111; }
.judgment-cell .judgment-partial { color: #175cd3; }
.judgment-cell .judgment-unknown { color: #b42318; }
.judgment-label { font-weight: 600; }
.excel-table .judgment-cell { padding-inline: 4px; }
.skill-tag-note { margin: 0; }
.skill-tags-cell .skill-stat-metadata { margin-top: 0; padding-top: 0; border-top: 0; }
.excel-table mark { color: inherit; background: #fff; text-decoration: underline; font-weight: 700; }

.editable-cell { cursor: text; }
.editable-cell:hover { box-shadow: inset 0 0 0 2px rgba(68, 114, 196, .35); }
.editable-cell.is-editing { padding: 4px; background: #fff !important; box-shadow: inset 0 0 0 2px var(--blue); }

.cell-editor {
  width: 100%;
  height: 72px;
  min-width: 0;
  margin: 0;
  padding: 7px 8px;
  border: 1px solid #6f8fbc;
  outline: 0;
  background: #fff;
  color: var(--ink);
  font: inherit;
  line-height: 1.45;
  resize: none;
}

input.cell-editor { height: 40px; text-align: center; }

.excel-table .separator-row,
.excel-table .separator-row td {
  height: 24px;
  min-height: 24px;
  padding: 0;
  background: #fff;
  border-left-color: transparent;
  border-right-color: transparent;
}

.excel-table .separator-row td {
  border-top: 2px solid #8fa7c6;
  border-bottom: 2px solid #8fa7c6;
}

.type-cell {
  width: 11%;
  background: #fff;
  color: #111;
  font-weight: 700;
  text-align: center;
}

.skill-name { font-weight: 700; color: inherit; }
.skill-name a { color: inherit; text-decoration-thickness: 1px; text-underline-offset: 3px; }
.skill-name a:hover { color: inherit; }
.rating-cell { text-align: center; font-weight: 800; color: inherit; white-space: nowrap; }

.action-cell { text-align: center; }

.add-skill-button {
  width: 32px;
  height: 32px;
  display: inline-grid;
  place-items: center;
  padding: 0;
  border: 1.5px solid #35445b;
  border-radius: 50%;
  background: #fff;
  color: #27364c;
  cursor: pointer;
  box-shadow: 0 1px 2px rgba(25,52,91,.1);
  transition: color .15s, border-color .15s, background .15s, transform .15s;
}

.add-skill-button span {
  display: block;
  font-size: 1.35rem;
  font-weight: 500;
  line-height: 1;
  transform: translateY(-1px);
}

.add-skill-button:hover { border-color: var(--blue); background: var(--blue-pale); transform: translateY(-1px); }
.add-skill-button.is-added { border-color: #3f8c5b; background: #edf8f0; color: #287043; }
.add-skill-button.is-added span { font-size: 1.05rem; font-weight: 700; transform: none; }

.sc-calculator[hidden] { display: none !important; }

.calculator-launcher {
  position: fixed;
  right: 18px;
  bottom: 18px;
  z-index: 30;
  min-width: 58px;
  min-height: 46px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 6px;
  border: 1px solid #b7c7dc;
  border-radius: 14px;
  background: var(--navy);
  color: #fff;
  box-shadow: 0 10px 28px rgba(20,39,67,.26);
  cursor: pointer;
}

.calculator-launcher:hover { background: var(--blue-strong); }
.calculator-launcher strong { padding: 5px 8px; border-radius: 8px; background: #fff; color: var(--navy); white-space: nowrap; }

.sc-calculator {
  position: fixed;
  right: 18px;
  bottom: 80px;
  z-index: 31;
  width: min(400px, calc(100vw - 24px));
  max-height: min(680px, calc(100vh - 110px));
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid #aabbd2;
  border-radius: 16px;
  background: #fff;
  box-shadow: 0 18px 50px rgba(20,39,67,.28);
}

.calculator-header {
  min-height: 48px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) 34px;
  align-items: center;
  gap: 7px;
  padding: 7px 10px;
  background: var(--navy);
  color: #fff;
}

.calculator-header > strong { min-width: 0; overflow: hidden; font-size: .92rem; text-align: center; text-overflow: ellipsis; white-space: nowrap; }
.calculator-sort-actions { display: flex; align-items: center; gap: 2px; }

.calculator-sort {
  width: auto;
  min-width: 42px;
  height: 34px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: #fff;
  cursor: pointer;
}

.calculator-sort:hover { background: rgba(255,255,255,.13); }
.calculator-sort.is-active { background: rgba(255,255,255,.18); }
.calculator-sort span { font-size: .75rem; font-weight: 700; line-height: 1; white-space: nowrap; }
.calculator-close { width: 34px; height: 34px; border: 0; border-radius: 50%; background: rgba(255,255,255,.13); color: #fff; font-size: 1.35rem; cursor: pointer; }

.calculator-plan-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
  padding: 8px 10px;
  background: #edf4fb;
  border-bottom: 1px solid #cad6e6;
}

.calculator-plan-actions button {
  min-height: 36px;
  border: 1px solid #9fb3cf;
  background: #fff;
  color: var(--navy);
  font-weight: 700;
  cursor: pointer;
}

.calculator-plan-actions button:hover { background: #dcecff; }
.calculator-plan-actions span { display: inline-grid; place-items: center; min-width: 22px; height: 22px; margin-left: 4px; border-radius: 11px; background: var(--navy); color: #fff; font-size: .74rem; }

.break-buttons {
  display: grid;
  grid-template-columns: repeat(3, 68px) minmax(62px, 1fr) 76px;
  gap: 5px;
  padding: 12px 14px 8px;
}

.break-buttons button {
  position: relative;
  min-height: 36px;
  padding: 4px 32px 4px 6px;
  border: 1px solid #aeb9c8;
  border-radius: 20px;
  background: #d1d4d7;
  color: #445063;
  font-weight: 700;
  font-size: .9rem;
  cursor: pointer;
  transition: background .16s, border-color .16s;
}

.break-buttons button::before {
  content: '';
  position: absolute;
  top: 50%;
  right: 4px;
  width: 24px;
  height: 24px;
  border: 1px solid #727b86;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 1px 3px rgba(0,0,0,.3);
  transform: translateY(-50%);
  transition: right .16s;
}

.break-buttons button.is-active {
  padding-right: 6px;
  padding-left: 32px;
  border-color: var(--blue-strong);
  background: var(--blue);
  color: #fff;
}

.break-buttons button.is-active::before { right: calc(100% - 28px); border-color: #fff; }

.break-buttons .calculator-details,
.break-buttons .calculator-mode-button {
  padding: 5px 10px;
  border-radius: 9px;
  background: #fff;
  color: var(--blue-strong);
}

.break-buttons .calculator-details::before,
.break-buttons .calculator-mode-button::before { display: none; }
.break-buttons .calculator-details:hover,
.break-buttons .calculator-mode-button:hover { background: var(--blue-pale); }
.break-buttons .calculator-details.is-active,
.break-buttons .calculator-mode-button.is-active { padding: 5px 10px; background: var(--navy); color: #fff; }

.calculator-skills { min-height: 86px; overflow-y: auto; border-top: 1px solid #dce4ef; }
.calculator-empty { padding: 30px 16px; color: var(--muted); text-align: center; }

.calculator-skill {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 60px 88px 30px;
  align-items: center;
  column-gap: 10px;
  row-gap: 8px;
  padding: 10px 12px;
  border-bottom: 1px solid #e2e8f1;
